   447→func runStatus(w io.Writer) error {
   448→	// Check if we're in a git repository
   449→	if _, repoErr := paths.RepoRoot(); repoErr != nil {
   450→		fmt.Fprintln(w, "✕ not a git repository")
   451→		return nil //nolint:nilerr // Not being in a git repo is a valid status, not an error
   452→	}
   453→
   454→	// Get absolute paths for settings files
   455→	settingsPath, err := paths.AbsPath(EntireSettingsFile)
   456→	if err != nil {
   457→		settingsPath = EntireSettingsFile
   458→	}
   459→	localSettingsPath, err := paths.AbsPath(EntireSettingsLocalFile)
   460→	if err != nil {
   461→		localSettingsPath = EntireSettingsLocalFile
   462→	}
   463→
   464→	// Check if either settings file exists
   465→	_, projectErr := os.Stat(settingsPath)
   466→	if projectErr != nil && !errors.Is(projectErr, fs.ErrNotExist) {
   467→		return fmt.Errorf("cannot access project settings file: %w", projectErr)
   468→	}
   469→	_, localErr := os.Stat(localSettingsPath)
   470→	if localErr != nil && !errors.Is(localErr, fs.ErrNotExist) {
   471→		return fmt.Errorf("cannot access local settings file: %w", localErr)
   472→	}
   473→	projectExists := projectErr == nil
   474→	localExists := localErr == nil
   475→
   476→	if !projectExists && !localExists {
   477→		fmt.Fprintln(w, "○ not set up (run `entire enable` to get started)")
   478→		return nil
   479→	}
   480→
   481→	// Load and display project settings (if exists)
   482→	if projectExists {
   483→		data, readErr := os.ReadFile(settingsPath) //nolint:gosec // path is from AbsPath or constant
   484→		if readErr != nil {
   485→			return fmt.Errorf("failed to read project settings: %w", readErr)
   486→		}
   487→		projectSettings := &EntireSettings{
   488→			Strategy: strategy.DefaultStrategyName,
   489→			Enabled:  true,
   490→		}
   491→		if unmarshalErr := json.Unmarshal(data, projectSettings); unmarshalErr != nil {
