   518→// formatSettingsStatus formats a settings status line.
   519→// Output format: "Project, enabled (manual-commit)" or "Local, disabled (auto-commit)"
   520→func formatSettingsStatus(prefix string, settings *EntireSettings) string {
   521→	displayName := settings.Strategy
   522→	if dn, ok := strategyInternalToDisplay[settings.Strategy]; ok {
   523→		displayName = dn
   524→	}
   525→
   526→	if settings.Enabled {
   527→		return fmt.Sprintf("%s, enabled (%s)", prefix, displayName)
   528→	}
   529→	return fmt.Sprintf("%s, disabled (%s)", prefix, displayName)
